import json
def load(p, mech_filter=None):
    d={}
    for line in open(p):
        if not line.strip(): continue
        r=json.loads(line)
        if mech_filter and r.get('mechanism')!=mech_filter:
            continue
        # for f02 no filter
        if mech_filter is None and 'case_id' not in r:
            print("BAD", list(r.keys())[:10])
            continue
        d[r['case_id']]=r
    return d
rows02=load("research/jev-bounded-judgment/phase1/followup-02-mimo-v2.6-flash/results/mimo_raw.ndjson")
print("rows02",len(rows02))
rows05=load("research/jev-bounded-judgment/phase1/followup-05-cross-family/staging/mimo/results/baselines_raw.ndjson", mech_filter='general_model')
print("rows05",len(rows05))
cases={}
for line in open("research/jev-bounded-judgment/phase1/cases.ndjson"):
    if line.strip():
        r=json.loads(line)
        cases[r['case_id']]=r
print("cases",len(cases),"sample keys",list(next(iter(cases.values())).keys()))
flips=[]
for cid in sorted(set(rows02)&set(rows05)):
    l02=rows02[cid]['prediction']['label']
    l05=rows05[cid]['prediction']['label']
    if l02!=l05:
        c=cases[cid]
        flips.append(cid)
        print(cid, "f02:",l02,"f05:",l05,"gt:",c.get('gt_answer'),"answerable:",c.get('answerable'),"area:",c.get('area'),"abstain_exp:",c.get('abstain_expected'))
print("total flips:",len(flips), flips)
def acc(d):
    n=correct=0
    errs=[]
    for cid,r in d.items():
        c=cases[cid]
        if c.get('answerable'):
            n+=1
            if r['prediction']['label']==c.get('gt_answer'):
                correct+=1
            else:
                errs.append(cid)
    return correct,n,correct/n if n else None,errs
print("f02 acc:",acc(rows02))
print("f05 acc:",acc(rows05))
